  "inlineSchema": `enum Role {
  super_admin // the developer: everything + the users page
  owner // the business owner: every business screen
}

// Everyone who can log in. The first super admin comes from ADMIN_EMAIL /
// ADMIN_PASSWORD; the super admin creates every other account from the site.
model Admin {
  id            String    @id @default(uuid())
  name          String    @default("")
  email         String    @unique
  password_hash String
  role          Role      @default(owner)
  is_active     Boolean   @default(true)
  created_at    DateTime  @default(now())
  updated_at    DateTime  @updatedAt
  sessions      Session[]

  @@map("admins")
}

// One row per signed-in device. Only the SHA-256 of the token is stored, so a
// leaked database row cannot be used to sign in.
model Session {
  id         String   @id @default(uuid())
  admin_id   String
  token_hash String   @unique
  expires_at DateTime
  created_at DateTime @default(now())
  admin      Admin    @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@index([admin_id])
  @@map("sessions")
}

// Business-wide settings, one row (id = 1), shared by every login.
model Setting {
  id            Int      @id @default(1)
  business_name String   @default("\u09B0\u09C7\u09A8\u09CD\u099F \u098F \u0995\u09BE\u09B0")
  updated_at    DateTime @updatedAt

  @@map("settings")
}

enum CarType {
  car
  micro
  hiace
  bus
  other
}

enum CarStatus {
  active
  maintenance
  inactive
}

model Car {
  id                  String    @id @default(uuid())
  name                String
  // Registration number. Unique among cars that are not deleted (checked in
  // the service, so a deleted car's number can be added again).
  number              String
  type                CarType   @default(car)
  status              CarStatus @default(active)
  fitness_expiry      DateTime? @db.Date
  tax_token_expiry    DateTime? @db.Date
  insurance_expiry    DateTime? @db.Date
  route_permit_expiry DateTime? @db.Date
  note                String?
  created_at          DateTime  @default(now())
  updated_at          DateTime  @updatedAt
  deleted_at          DateTime?

  trips    Trip[]
  expenses Expense[]
  drivers  Driver[]

  @@index([deleted_at])
  @@index([number])
  @@map("cars")
}

enum DriverStatus {
  active
  inactive
}

model Driver {
  id             String       @id @default(uuid())
  name           String
  phone          String
  license_number String?
  address        String?
  joined_at      DateTime?    @db.Date
  default_car_id String?
  status         DriverStatus @default(active)
  note           String?
  created_at     DateTime     @default(now())
  updated_at     DateTime     @updatedAt
  deleted_at     DateTime?

  default_car Car?      @relation(fields: [default_car_id], references: [id], onDelete: SetNull)
  trips       Trip[]
  expenses    Expense[]

  @@index([deleted_at])
  @@map("drivers")
}

enum ExpenseCategory {
  fuel
  toll
  parking
  repair
  driver_payment
  food
  other
}

model Expense {
  id           String          @id @default(uuid())
  expense_date DateTime        @db.Date
  category     ExpenseCategory
  amount       Decimal         @db.Decimal(12, 2)
  car_id       String?
  driver_id    String?
  trip_id      String?
  note         String?
  created_at   DateTime        @default(now())
  updated_at   DateTime        @updatedAt
  deleted_at   DateTime?

  car    Car?    @relation(fields: [car_id], references: [id], onDelete: SetNull)
  driver Driver? @relation(fields: [driver_id], references: [id], onDelete: SetNull)
  trip   Trip?   @relation(fields: [trip_id], references: [id], onDelete: SetNull)

  @@index([expense_date])
  @@index([car_id, expense_date])
  @@index([driver_id, expense_date])
  @@index([trip_id])
  @@map("expenses")
}

generator client {
  provider = "prisma-client"
  output   = "../../src/generated/prisma"
}

datasource db {
  provider = "postgresql"
}

enum TripStatus {
  running
  completed
  cancelled
}

// One trip = the car left the garage once. Due is fare - paid (computed).
model Trip {
  id             String     @id @default(uuid())
  trip_date      DateTime   @db.Date
  car_id         String
  driver_id      String
  from_place     String
  to_place       String
  customer_name  String?
  customer_phone String?
  out_time       String? // "HH:mm"
  return_time    String? // "HH:mm"
  fare           Decimal    @db.Decimal(12, 2)
  paid           Decimal    @default(0) @db.Decimal(12, 2)
  status         TripStatus @default(completed)
  note           String?
  created_at     DateTime   @default(now())
  updated_at     DateTime   @updatedAt
  deleted_at     DateTime?

  car      Car       @relation(fields: [car_id], references: [id], onDelete: Restrict)
  driver   Driver    @relation(fields: [driver_id], references: [id], onDelete: Restrict)
  expenses Expense[]

  @@index([trip_date])
  @@index([car_id, trip_date])
  @@index([driver_id, trip_date])
  @@map("trips")
}
`,
